import{_ as l,a0 as o,w as d,s as r,ao as p,I as n,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"三件可以用 systemd 做的令人驚訝的事情 | LCTT x X-CMD","titleTemplate":false,"description":"三件可以用 systemd 做的令人驚訝的事情 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三件可以用 systemd 做的令人驚訝的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三件可以用 systemd 做的令人驚訝的事情 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230323.2 ⭐️ 3 surprising things Linux sysadmins can do with systemd","title":"三件可以用 systemd 做的令人驚訝的事情","tag":"202304","desc":""},"relativePath":"202304/20230323.2 ⭐️ 3 surprising things Linux sysadmins can do with systemd.md","filePath":"[post].md"}'),u={name:"202304/20230323.2 ⭐️ 3 surprising things Linux sysadmins can do with systemd.md"};function m(g,s,y,f,k,b){const e=o("Link");return d(),r("div",null,[s[41]||(s[41]=p('<h1 id="三件可以用-systemd-做的令人驚訝的事情" tabindex="-1">三件可以用 systemd 做的令人驚訝的事情 <a class="header-anchor" href="#三件可以用-systemd-做的令人驚訝的事情" aria-label="Permalink to “三件可以用 systemd 做的令人驚訝的事情”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/02/135545u0rwtqdemqefme3e.jpg" alt=""></p><blockquote><p>它不僅僅是為了讓你的電腦啓動得更快。</p></blockquote><p>當 systemd 剛問世時，有很多關於它能加快啓動時間的消息。這項功能對大多數人都有吸引力（對那些不重啓的人來説就不那麼重要了），所以在很多方面，這也是它今天仍然擁有的聲譽。雖然 systemd 確實是在啓動過程中並行啓動服務起到了作用，但它的作用遠不止於此。以下是你可能沒有意識到 systemd 可以做的三件事，但你應該好好利用。</p><h3 id="_1、簡化-linux-ps" tabindex="-1">1、簡化 Linux ps <a class="header-anchor" href="#_1、簡化-linux-ps" aria-label="Permalink to “1、簡化 Linux ps”">​</a></h3><p>如果你曾經使用過 <code>ps</code>，甚至只是 <code>top</code> 命令，那麼你就會知道你的電腦一直都在運行數百個進程。有時，這正是你需要的信息，以便了解你的計算機或其用户在做什麼。其他時候，你真正需要的是一個總體的概覽。</p>',6)),n("p",null,[s[1]||(s[1]=n("code",null,"systemd-cgtop",-1)),s[2]||(s[2]=t(" 命令提供了一個基於",-1)),s[3]||(s[3]=n("ruby",null,[t("控制組"),n("rt",null,"cgroup")],-1)),s[4]||(s[4]=t("任務安排的計算機負載的簡單視圖。",-1)),i(e,{href:"https://www.redhat.com/sysadmin/cgroups-part-four?intcmp=7013a000002qLH8AAM"},{default:a(()=>[...s[0]||(s[0]=[t("控制組",-1)])]),_:1}),s[5]||(s[5]=t(" 對現代 Linux 很重要，基本上是容器和 Kubernetes 的底層支持結構（這也是雲計算可以擴展的原因），但它們也是家庭電腦上的有用結構。例如，從 ",-1)),s[6]||(s[6]=n("code",null,"systemd-cgtop",-1)),s[7]||(s[7]=t(" 的輸出中，你可以看到用户進程的負載，而不是系統進程：",-1))]),s[42]||(s[42]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Control Group               Proc+   %CPU   Memory  Input/s Output/s</span></span>
<span class="line"><span>/                             183    5.0     1.6G       0B     3.0M</span></span>
<span class="line"><span>user.slice                      4    2.8     1.1G       0B   174.7K</span></span>
<span class="line"><span>user.slice/user-1000.slice      4    2.8   968.2M       0B   174.7K</span></span>
<span class="line"><span>system.slice                   65    2.2     1.5G       0B     2.8M</span></span></code></pre></div><p>你也可以只查看你的用户空間進程，或者查看用户空間進程和內核線程。</p><p>這絕不是對 <code>top</code> 或 <code>ps</code> 的替代，而是從一個不同的、獨特的角度來觀察你的系統。在運行容器時，它可能是至關重要的，因為容器使用控制組。</p><h3 id="_2、linux-定時任務" tabindex="-1">2、Linux 定時任務 <a class="header-anchor" href="#_2、linux-定時任務" aria-label="Permalink to “2、Linux 定時任務”">​</a></h3>`,4)),n("p",null,[i(e,{href:"https://opensource.com/article/17/11/how-use-cron-linux"},{default:a(()=>[...s[8]||(s[8]=[t("Cron",-1)])]),_:1}),s[9]||(s[9]=t(" 是 Linux 的一個經典組件。當你想安排一些事情定期發生時，你會使用 Cron。它很可靠，而且相當好地集成到你的系統中。",-1))]),s[43]||(s[43]=n("p",null,"問題是，Cron 並不瞭解有些計算機會被關閉。如果你有一個安排在午夜的 Cron 任務，但你每天在 23:59 關閉你的電腦，那麼你的 Cron 任務就永遠不會運行。Cron 沒有任何工具可以檢測到一夜之間錯過了工作。",-1)),n("p",null,[s[11]||(s[11]=t("作為對這個問題的回答，有一個很好的 ",-1)),i(e,{href:"https://opensource.com/article/21/2/linux-automation"},{default:a(()=>[...s[10]||(s[10]=[t("Anacron",-1)])]),_:1}),s[12]||(s[12]=t("，但它不像 Cron 那樣集成的好。要讓 Anacron 運行，你需要做很多設置。",-1))]),s[44]||(s[44]=p(`<p>第二個選擇是 systemd 計時器。和 Cron 一樣，它也是內置的，可以隨時使用。你需要寫一個單元文件，這肯定比單行的 Crontab 條目多，但也很簡單。例如，這裏有一個單元文件，在開機 30 分鐘後運行一個假想的備份腳本，但每天只運行一次。這可以確保我的電腦得到備份，並防止它每天嘗試備份超過一次。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=Backup</span></span>
<span class="line"><span>Requires=myBackup.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Timer]</span></span>
<span class="line"><span>OnBootSec=30min</span></span>
<span class="line"><span>OnUnitActiveSec=1d</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=timers.target</span></span></code></pre></div><p>當然，你也可以干預並提示運行一個任務。多虧了 <code>OnUnitActiveSec</code> 指令，systemd 不會試圖運行你手動激活的作業。</p><h3 id="_3、運行-linux-容器" tabindex="-1">3、運行 Linux 容器 <a class="header-anchor" href="#_3、運行-linux-容器" aria-label="Permalink to “3、運行 Linux 容器”">​</a></h3>`,4)),n("p",null,[s[15]||(s[15]=t("容器使啓動一個複雜的服務變得非常容易。你可以在短短幾分鐘內運行一個 ",-1)),i(e,{href:"https://opensource.com/education/16/3/mattermost-open-source-chat"},{default:a(()=>[...s[13]||(s[13]=[t("Mattermost",-1)])]),_:1}),s[16]||(s[16]=t(" 或 Discourse 服務器。在某些情況下，困難的部分是在你運行容器後管理和監控它們。Podman 使得管理它們變得容易，但是用什麼來管理 Podman 呢？嗯，",-1)),i(e,{href:"https://www.redhat.com/sysadmin/podman-run-pods-systemd-services?intcmp=7013a000002qLH8AAM"},{default:a(()=>[...s[14]||(s[14]=[t("你可以使用 systemd",-1)])]),_:1}),s[17]||(s[17]=t("。",-1))]),s[45]||(s[45]=p('<p>Podman 有一個內置的命令來生成單元文件，這樣你的容器就可以被 systemd 管理和監控：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman generate systemd --new --files --name example_pod</span></span></code></pre></div><p>然後你所要做的就是啓動服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl --user start pod-example_pod.service</span></span></code></pre></div><p>和其他服務一樣，systemd 確保你的容器莢在任何情況下都能運行。它記錄問題，你可以用 <code>journalctl</code> 和其他重要的日誌來查看，你也可以用 <code>systemd-cgtop</code> 在控制組中監控它的活動。</p>',5)),n("p",null,[s[19]||(s[19]=t("它不是 ",-1)),i(e,{href:"https://www.redhat.com/en/technologies/cloud-computing/openshift/aws?intcmp=7013a000002qLH8AAM"},{default:a(()=>[...s[18]||(s[18]=[t("Kubernetes 平台",-1)])]),_:1}),s[20]||(s[20]=t("，但對於一兩個容器來説，你只需要在可靠和可預測的基礎上提供服務，Podman 和 systemd 是一對很棒的組合。",-1))]),s[46]||(s[46]=n("h3",{id:"下載-systemd-電子書",tabindex:"-1"},[t("下載 systemd 電子書 "),n("a",{class:"header-anchor",href:"#下載-systemd-電子書","aria-label":"Permalink to “下載 systemd 電子書”"},"​")],-1)),n("p",null,[s[23]||(s[23]=t("systemd 的內容還有很多，你可以從作者 ",-1)),i(e,{href:"https://opensource.com/users/dboth"},{default:a(()=>[...s[21]||(s[21]=[t("David Both",-1)])]),_:1}),s[24]||(s[24]=t(" 的新書《",-1)),i(e,{href:"https://opensource.com/downloads/pragmatic-guide-systemd-linux"},{default:a(()=>[...s[22]||(s[22]=[t("systemd 實用指南",-1)])]),_:1}),s[25]||(s[25]=t("》中瞭解基礎知識，以及很多實用的技巧。",-1))]),s[47]||(s[47]=n("hr",null,null,-1)),n("p",null,[s[27]||(s[27]=t("via: ",-1)),i(e,{href:"https://opensource.com/article/23/3/3-things-you-didnt-know-systemd-could-do"},{default:a(()=>[...s[26]||(s[26]=[t("https://opensource.com/article/23/3/3-things-you-didnt-know-systemd-could-do",-1)])]),_:1})]),n("p",null,[s[32]||(s[32]=t("作者：",-1)),i(e,{href:"https://opensource.com/users/alansmithee"},{default:a(()=>[...s[28]||(s[28]=[t("Alan Smithee",-1)])]),_:1}),s[33]||(s[33]=t(" 選題：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:a(()=>[...s[29]||(s[29]=[t("lkxed",-1)])]),_:1}),s[34]||(s[34]=t(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[30]||(s[30]=[t("wxy",-1)])]),_:1}),s[35]||(s[35]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[31]||(s[31]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[38]||(s[38]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[36]||(s[36]=[t("LCTT",-1)])]),_:1}),s[39]||(s[39]=t(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[37]||(s[37]=[t("Linux中國",-1)])]),_:1}),s[40]||(s[40]=t(" 榮譽推出",-1))])])}const C=l(u,[["render",m]]);export{h as __pageData,C as default};
